WITH base AS (SELECT id, order_id, method, amount, paid_at, status, FLOOR(amount) AS amount_whole, ROUND(amount * 1.1, 2) AS amount_scaled, COALESCE(method, 'OTHER') AS method_filled FROM payments WHERE status IN ('REFUNDED', 'FAILED')), scored AS (SELECT *, NTILE(5) OVER (PARTITION BY order_id ORDER BY amount_scaled DESC, id) AS amount_scaled_bucket, AVG(amount_scaled) OVER w_running AS amount_scaled_avg_90d, ROUND(amount / SUM(amount) OVER (PARTITION BY status), 4) AS amount_share, AVG(amount_scaled) OVER (ORDER BY amount, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS amount_scaled_avg_6 FROM base WINDOW w_running AS (PARTITION BY order_id, method ORDER BY CAST(paid_at AS BIGINT) RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW)), deduped AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY method ORDER BY amount_scaled_avg_6 NULLS LAST) AS latest_rank FROM scored) ranked WHERE latest_rank = 1), base_payments AS (SELECT id, order_id, method, paid_at, status, amount_whole, method_filled, amount_scaled_bucket, amount_scaled_avg_90d, amount_share, amount_scaled_avg_6, latest_rank, CASE WHEN amount_scaled_avg_90d >= 79 THEN 'High' WHEN amount_scaled_avg_90d >= 35 THEN 'Medium' ELSE 'Low' END AS amount_scaled_avg_90d_tier, amount * amount_whole AS amount_times_amount_whole, COALESCE(method, 'OTHER') AS resolved_method FROM deduped WHERE paid_at >= DATE '2023-11-07' AND amount_scaled_avg_6 BETWEEN 35 AND 41), prev_events AS (SELECT *, LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) AS prev_paid_at FROM base_payments), flagged AS (SELECT *, CASE WHEN prev_paid_at IS NULL OR paid_at > prev_paid_at + INTERVAL '14' DAY THEN 1 ELSE 0 END AS is_new_session FROM prev_events), sessions_payments AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged), enriched AS (SELECT src.*, b.shipping_fee FROM sessions_payments src INNER JOIN orders b ON src.order_id = b.id), with_dims AS (SELECT src.*, d.shipping_fee AS order_shipping_fee, d.channel, d.discount FROM enriched src INNER JOIN orders d ON src.order_id = d.id) SELECT s.id, s.order_id, s.method, s.paid_at, s.amount_whole, s.amount_scaled_bucket, s.amount_scaled_avg_6, s.resolved_method, s.is_new_session, CASE WHEN method RLIKE '^(promptpay|paypal)$' THEN 'EXTENDED' ELSE 'GROUP_B' END AS method_zone, (SELECT AVG(x.amount) FROM payments x WHERE x.order_id = s.order_id) AS avg_payment_amount FROM with_dims s ORDER BY is_new_session NULLS FIRST;
